import type {AiFileFindings, AiFinding} from '../types/ai-findings'

export function areAiFileFindingsSame(filesA: AiFileFindings[], filesB: AiFileFindings[]): boolean {
  if (filesA.length !== filesB.length) {
    return false
  }

  // We only check if each file in filesA has a corresponding file in filesB,
  // but not the reverse (filesB subset of filesA). This relies on the assumption
  // that each file path appears only once in each array, which is enforced by
  // the data structure but not validated here.
  for (const fileA of filesA) {
    const fileB = filesB.find(f => f.filePath === fileA.filePath)
    if (!fileB) {
      return false
    }
    if (
      fileA.lastPushAt !== fileB.lastPushAt ||
      fileA.commitOid !== fileB.commitOid ||
      !areFindingsArraysSame(fileA.findings, fileB.findings)
    ) {
      return false
    }
  }
  return true
}

/* Returns:
    - existingFindingsCount - Number of findings in "current" and in "next"
    - newFindingsCount - Number of findings in "next" but not in "current"
    - deprecatedFindingsCount - Number of findings in "current" but not in "next"
*/
export function getAnalyticsFindingsCount(
  current: AiFileFindings[],
  next: AiFileFindings[],
): {existingFindingsCount: number; newFindingsCount: number; deprecatedFindingsCount: number} {
  const setCurrentFindings = new Set<string>()
  const setNextFindings = new Set<string>()

  for (const {filePath, findings} of current) {
    for (const finding of findings) {
      setCurrentFindings.add(
        `${filePath}|${finding.message}|${finding.startLine}|${finding.endLine}|${finding.startColumn}|${finding.endColumn}`,
      )
    }
  }

  for (const {filePath, findings} of next) {
    for (const finding of findings) {
      setNextFindings.add(
        `${filePath}|${finding.message}|${finding.startLine}|${finding.endLine}|${finding.startColumn}|${finding.endColumn}`,
      )
    }
  }

  return {
    existingFindingsCount: getCommonFindingsCount(setCurrentFindings, setNextFindings),
    newFindingsCount: getFindingsCountNotInB(setNextFindings, setCurrentFindings),
    deprecatedFindingsCount: getFindingsCountNotInB(setCurrentFindings, setNextFindings),
  }
}

export function getCommonFindingsCount(setA: Set<string>, setB: Set<string>): number {
  let commonCount = 0
  for (const item of setA) {
    if (setB.has(item)) {
      commonCount++
    }
  }

  return commonCount
}

export function getFindingsCountNotInB(setA: Set<string>, setB: Set<string>): number {
  let countNotInB = 0
  for (const item of setA) {
    if (!setB.has(item)) {
      countNotInB++
    }
  }

  return countNotInB
}

export function getFilesWithNewFindings(current: AiFileFindings[], next: AiFileFindings[]): string[] {
  const filesWithNewFindings = new Set<string>()

  for (const {filePath, findings} of next) {
    const oldFile = current.find(f => f.filePath === filePath)

    for (const finding of findings) {
      const isNew = !oldFile || !oldFile.findings.some(f => areFindingsSame(f, finding))
      if (isNew) filesWithNewFindings.add(filePath)
    }
  }

  return Array.from(filesWithNewFindings)
}

function areFindingsArraysSame(findingsA: AiFinding[], findingsB: AiFinding[]): boolean {
  if (findingsA.length !== findingsB.length) {
    return false
  }
  for (const findingA of findingsA) {
    const found = findingsB.some(findingB => areFindingsSame(findingA, findingB))
    if (!found) {
      return false
    }
  }
  for (const findingB of findingsB) {
    const found = findingsA.some(findingA => areFindingsSame(findingA, findingB))
    if (!found) {
      return false
    }
  }
  return true
}

function areFindingsSame(findingA: AiFinding, findingB: AiFinding): boolean {
  return (
    findingA.message === findingB.message &&
    findingA.startLine === findingB.startLine &&
    findingA.endLine === findingB.endLine &&
    findingA.startColumn === findingB.startColumn &&
    findingA.endColumn === findingB.endColumn
    // Intentionally ignoring fixFiles comparison for simplicity
  )
}
