import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'

export type BulkFindingEntry = {
  stableId: string
  filePath: string
}

export type RuleFindingsBulkStateMutationRequest = {
  ruleId: string
  findings: BulkFindingEntry[]
  state: string
}

export function useRuleFindingsBulkStateMutation(
  path: string,
): UseMutationResult<void, Error, RuleFindingsBulkStateMutationRequest> {
  return useMutation({
    mutationFn: request => {
      return fetchJson(path, {
        method: 'PATCH',
        defaultErrorMessage: 'Could not update findings state, please try again later.',
        body: {
          rule_id: request.ruleId,
          state: request.state,
          findings: request.findings.map(f => ({
            stable_id: f.stableId,
            file_path: f.filePath,
          })),
        },
      })
    },
  })
}
