import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'
import type {CommitAutofixRequest} from '../types/commit-autofix-request'
import type {CommitAutofixResponse} from '../types/commit-autofix-response'

export function useCommitAutofixMutation(
  path: string,
): UseMutationResult<CommitAutofixResponse, Error, CommitAutofixRequest> {
  return useMutation({
    mutationKey: ['commit-autofix', path],
    mutationFn: async request => {
      const response = await fetchJson<CommitAutofixResponse>(path, {
        method: 'POST',
        body: {
          name: request.name,
          create_new_branch: request.createNewBranch,
          create_draft_pr: request.createDraftPR,
          commit_message: request.commitMessage,
          extended_description: request.extendedDescription,
        },
      })
      return response
    },
  })
}
