import type {AiFileFindings} from '../types/ai-findings'

export function generateAiFindingsFixPrompt(fileFindings: AiFileFindings[]): string {
  const findings = fileFindings
    .flatMap(file => file.findings)
    .map(f => {
      return {
        message: f.message,
        fixFiles: f.fixFiles.map(ff => ({
          filePath: ff.filePath,
          diff: ff.diff,
        })),
      }
    })

  return `
    Please apply the following diffs and create a pull request.
    Once the PR is ready, give it a title based on the messages of the fixes being applied.

    ${JSON.stringify(findings)}
  `
}
