import {RuleSeverity} from '@github-ui/code-scanning-shared/types/rule-severity'

export const RuleSeverityFilterOption = {
  All: 'All',
  Error: 'Error',
  Warning: 'Warning',
  Note: 'Note',
}
export type RuleSeverityFilterOption = (typeof RuleSeverityFilterOption)[keyof typeof RuleSeverityFilterOption]

export const severityOptions: RuleSeverityFilterOption[] = Object.values(RuleSeverityFilterOption)

export function parseSeverity(severity: string | null): RuleSeverityFilterOption {
  if (!severity) {
    return RuleSeverityFilterOption.All
  }

  switch (severity.toLowerCase()) {
    case RuleSeverity.Note:
      return RuleSeverityFilterOption.Note
    case RuleSeverity.Warning:
      return RuleSeverityFilterOption.Warning
    case RuleSeverity.Error:
      return RuleSeverityFilterOption.Error
    default:
      return RuleSeverityFilterOption.All
  }
}
