import {LanguageDot} from '@github-ui/copilot-markdown/extensions/code-blocks/LanguageDot'
import {getLanguageColor, mapLanguageStringToRuleLanguageFilterOption, type RuleLanguage} from '../types/rule-language'

export interface RuleLanguageLabelProps {
  language: RuleLanguage
}

export function RuleLanguageLabel({language}: RuleLanguageLabelProps) {
  return (
    <div className="d-flex flex-row flex-items-center gap-1">
      <LanguageDot color={getLanguageColor(language)} variant="compact" />
      {/* Display filter option because it is the user-friendly name of the language */}
      <div className="text-semibold color-fg-default">{mapLanguageStringToRuleLanguageFilterOption(language)}</div>
    </div>
  )
}
