import {codeQualityRuleFindingsPath} from '@github-ui/paths'
import {useRuleFindingsQuery} from '../hooks/use-rule-findings-query'
import {PrevNextPagination} from '@github-ui/code-scanning-shared/components/PrevNextPagination'
import type {Cursor} from '@github-ui/code-scanning-shared/types/cursor'
import {RuleFindingsLoading} from './RuleFindingsLoading'
import {ErrorState} from './ErrorState'
import {UnderlineNav} from '@primer/react'
import {FindingState} from '../types/rule-finding'
import {Blankslate} from '@primer/react/experimental'
import styles from './RuleFindings.module.css'
import {useRuleFindingsParams} from '../hooks/use-rule-findings-params'
import {CodeQualityFileFrame} from './CodeQualityFileFrame'
import {RuleFindingsFilter} from './RuleFindingsFilter'
import {RuleFindingsBulkActions} from './RuleFindingsBulkActions'
import {useCallback, useMemo, useState} from 'react'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {getActiveStatesFromQuery} from '../utils/get-active-states-from-query'
import {getFilteredFindingsCount} from '../utils/get-filtered-findings-count'

export interface RuleFindingsProps {
  owner: string
  repo: string
  defaultBranch: string
  branchListCacheKey: string
  ruleId: string
  ruleTitle: string
  canAutofix: boolean
  canDismiss: boolean
  hasRepoWriteAccess: boolean
}

export function RuleFindings({
  owner,
  repo,
  defaultBranch,
  branchListCacheKey,
  ruleId,
  ruleTitle,
  canAutofix,
  canDismiss,
  hasRepoWriteAccess,
}: RuleFindingsProps) {
  const {cursor, selectedTab, filterQuery, onCursorChange, onSelectTab, onFilterQueryChange} = useRuleFindingsParams()
  const isDismissed = selectedTab === FindingState.Dismissed
  const ruleFindingsPath = codeQualityRuleFindingsPath({owner, repo, ruleId})

  const showPageImprovementsFFEnabled = isFeatureEnabled('code_quality_backlog_rule_show')

  const [selectedItems, setSelectedItems] = useState<Set<string>>(() => new Set<string>())

  const onSelect = useCallback((stableId: string, selected: boolean) => {
    setSelectedItems(prev => {
      const next = new Set(prev)
      if (selected) {
        next.add(stableId)
      } else {
        next.delete(stableId)
      }
      return next
    })
  }, [])

  const clearSelection = useCallback(() => {
    setSelectedItems(new Set())
  }, [])

  const handleCursorChange = useCallback(
    (newCursor: Cursor | null) => {
      clearSelection()
      onCursorChange(newCursor)
    },
    [clearSelection, onCursorChange],
  )

  const findingsRequest = showPageImprovementsFFEnabled
    ? {cursor, query: filterQuery || undefined}
    : {cursor, state: selectedTab}

  const {data, isPending, isError} = useRuleFindingsQuery(ruleFindingsPath, findingsRequest, {
    refetchInterval: query => {
      return query.state.data?.ruleFindings?.some(finding => finding.suggestedFix?.state === 'pending') ? 10_000 : false
    },
  })

  // Use a separate query for retrieving the counts
  // This avoids flickering the counts when switching tabs
  const countsRequest = showPageImprovementsFFEnabled ? {cursor: null} : {cursor: null, state: FindingState.Open}
  const {data: countsData} = useRuleFindingsQuery(ruleFindingsPath, countsRequest)

  const ruleFindings = useMemo(() => data?.ruleFindings || [], [data?.ruleFindings])
  const openCount = countsData?.openCount || 0
  const dismissedCount = countsData?.dismissedCount || 0
  const activeStates = getActiveStatesFromQuery(filterQuery)
  const totalCount = getFilteredFindingsCount(openCount, dismissedCount, activeStates)

  const onToggleSelectAll = useCallback(
    (selectAll: boolean) => {
      if (selectAll) {
        setSelectedItems(new Set(ruleFindings.map(f => f.stableId)))
      } else {
        setSelectedItems(new Set())
      }
    },
    [ruleFindings],
  )

  if (isPending) {
    return (
      <div className="tmp-mt-3">
        <RuleFindingsLoading rowCount={5} />
      </div>
    )
  }
  if (isError) {
    return <ErrorState message="Rule findings data could not be loaded right now." />
  }

  return (
    <>
      {!showPageImprovementsFFEnabled && (
        <UnderlineNav aria-label="Select a tab" className={styles.findingTabs}>
          <UnderlineNav.Item
            counter={openCount}
            aria-current={selectedTab === FindingState.Open ? 'location' : undefined}
            onSelect={e => {
              e.preventDefault()
              onSelectTab(FindingState.Open)
            }}
          >
            Open
          </UnderlineNav.Item>
          <UnderlineNav.Item
            counter={dismissedCount}
            aria-current={selectedTab === FindingState.Dismissed ? 'location' : undefined}
            onSelect={e => {
              e.preventDefault()
              onSelectTab(FindingState.Dismissed)
            }}
          >
            Dismissed
          </UnderlineNav.Item>
        </UnderlineNav>
      )}

      {showPageImprovementsFFEnabled && (
        <div className={styles.findingsFilter}>
          <RuleFindingsFilter query={filterQuery} onQueryChange={onFilterQueryChange} />
        </div>
      )}

      {ruleFindings.length === 0 && (
        <Blankslate className={styles.blankslate}>
          <Blankslate.Heading>{`No${showPageImprovementsFFEnabled ? ' ' : ` ${selectedTab} `}findings available.`}</Blankslate.Heading>
          <Blankslate.Description>
            This rule doesn&apos;t have code quality findings that match your filter criteria.
          </Blankslate.Description>
        </Blankslate>
      )}

      {showPageImprovementsFFEnabled && canDismiss && ruleFindings.length > 0 && (
        <RuleFindingsBulkActions
          selectedItems={selectedItems}
          findings={ruleFindings}
          totalCount={totalCount || 0}
          ruleId={ruleId}
          ruleFindingsPath={ruleFindingsPath}
          onSuccess={clearSelection}
          onToggleSelectAll={onToggleSelectAll}
        />
      )}

      {ruleFindings.map(finding => (
        <div key={finding.stableId} className="tmp-mb-3">
          <CodeQualityFileFrame
            finding={finding}
            owner={owner}
            repo={repo}
            defaultBranch={defaultBranch}
            branchListCacheKey={branchListCacheKey}
            canAutofix={canAutofix}
            ruleId={ruleId}
            ruleTitle={ruleTitle}
            canDismiss={canDismiss}
            isDismissed={showPageImprovementsFFEnabled ? finding.findingState === FindingState.Dismissed : isDismissed}
            hasRepoWriteAccess={hasRepoWriteAccess}
            isSelected={selectedItems.has(finding.stableId)}
            onSelect={
              showPageImprovementsFFEnabled && canDismiss ? selected => onSelect(finding.stableId, selected) : undefined
            }
          />
        </div>
      ))}

      <PrevNextPagination
        onCursorChange={handleCursorChange}
        prevCursor={data?.prevCursor}
        nextCursor={data?.nextCursor}
      />
    </>
  )
}
