import type {Cursor} from '@github-ui/code-scanning-shared/types/cursor'

export interface GetRulesRequest {
  cursor: Cursor | null
}

export function addGetRulesRequestToPath(path: string, request: GetRulesRequest): string {
  const url = new URL(path, window.location.origin)

  addGetRulesRequestToParams(url.searchParams, request)

  // Do not include the hostname since we're always on the same domain
  return `${url.pathname}?${url.searchParams.toString()}`
}

export function addGetRulesRequestToParams(params: URLSearchParams, request: GetRulesRequest) {
  if (request.cursor) {
    if ('before' in request.cursor) {
      params.set('before', request.cursor.before)
    } else {
      params.set('after', request.cursor.after)
    }
  }
}
