import {parseCursor, serializeCursor, type Cursor} from '@github-ui/code-scanning-shared/types/cursor'
import {useSearchParams} from '@github-ui/use-navigate'
import {useMemo} from 'react'

export function useFilterParams() {
  const [params, setParams] = useSearchParams()
  const cursor = useMemo(() => parseCursor(params), [params])
  const query = params.get('query') || ''

  const onCursorChange = (newCursor: Cursor | null) => {
    setParams(
      prevParams => {
        const next = new URLSearchParams(prevParams)
        serializeCursor(newCursor, next)
        return next
      },
      {
        preventScrollReset: true,
      },
    )
  }

  const manipulateQuery = (manipulator: (currentQuery: string) => string) => {
    setParams(
      prevParams => {
        const next = new URLSearchParams(prevParams)
        const currentQuery = next.get('query') || ''
        const newQuery = manipulator(currentQuery)
        if (newQuery.trim() === '') {
          next.delete('query')
        } else {
          next.set('query', newQuery)
        }
        serializeCursor(null, next)
        return next
      },
      {
        preventScrollReset: true,
      },
    )
  }

  const onQueryChange = (newQuery: string) => {
    manipulateQuery(() => newQuery)
  }

  return {
    cursor,
    query,
    onCursorChange,
    onQueryChange,
    manipulateQuery,
  }
}
