import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemMetadata} from '@github-ui/list-view/ListItemMetadata'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {codeQualityShowPath, commitPath} from '@github-ui/paths'
import {CounterLabel, Link, RelativeTime} from '@primer/react'

import {FindingSeverityBadge} from './FindingSeverityBadge'
import {RuleCategoryBadge} from './RuleCategoryBadge'
import {RuleLanguageLabel} from './RuleLanguageLabel'
import type {Rule} from '../types/rule'
import type {ScanMetadata} from '../types/scan-metadata'
import {FindingState} from '../types/rule-finding'
import {getFilteredFindingsCount} from '../utils/get-filtered-findings-count'

export interface RuleListItemProps {
  rule: Rule
  owner: string
  repo: string
  branch: string
  lastScan: ScanMetadata
  activeStates: FindingState[]
}

export function RuleListItem({rule, owner, repo, branch, lastScan, activeStates}: RuleListItemProps) {
  const shortCommitId = lastScan.commitOid.slice(0, 7)
  const allDismissed = rule.openCount === 0 && rule.dismissedCount > 0
  const counterValue = getFilteredFindingsCount(rule.openCount, rule.dismissedCount, activeStates)
  const onlyDismissedFilter = activeStates.includes(FindingState.Dismissed) && !activeStates.includes(FindingState.Open)
  const showDismissedState = allDismissed || onlyDismissedFilter

  return (
    <ListItem
      className="pl-2"
      title={
        <ListItemTitle
          value={rule.title}
          href={codeQualityShowPath({
            owner,
            repo,
            ruleId: rule.ruleId,
            state: showDismissedState ? 'dismissed' : undefined,
          })}
          anchorClassName={allDismissed ? 'color-fg-muted' : undefined}
          trailingBadges={[
            <CounterLabel key="findings-count" className="ml-2 fgColor-muted">
              {counterValue}
            </CounterLabel>,
          ]}
        />
      }
      metadata={
        <ListItemMetadata className="gap-2">
          <RuleCategoryBadge category={rule.category} />
          <FindingSeverityBadge severity={rule.severity} />
          <RuleLanguageLabel language={rule.language} />
        </ListItemMetadata>
      }
    >
      <ListItemMainContent>
        <ListItemDescription className={allDismissed ? 'color-fg-muted' : undefined}>
          Detected by CodeQL · Last seen <RelativeTime date={new Date(lastScan.timestamp)} /> on {branch} in{' '}
          <Link
            inline
            className="text-mono color-fg-default"
            href={commitPath({owner, repo, commitish: lastScan.commitOid})}
          >
            {shortCommitId}
          </Link>
        </ListItemDescription>
      </ListItemMainContent>
    </ListItem>
  )
}
