import {parseCursor, serializeCursor, type Cursor} from '@github-ui/code-scanning-shared/types/cursor'
import {useSearchParams} from '@github-ui/use-navigate'
import {useMemo} from 'react'
import {FindingState} from '../types/rule-finding'

export function useRuleFindingsParams() {
  const [params, setParams] = useSearchParams()
  const cursor = useMemo(() => parseCursor(params), [params])
  const selectedTab = useMemo(() => {
    const tabParam = params.get('state')
    return tabParam && Object.values(FindingState).includes(tabParam) ? tabParam : FindingState.Open
  }, [params])
  const filterQuery = useMemo(() => params.get('query') || 'is:open', [params])

  const onCursorChange = (newCursor: Cursor | null) => {
    setParams(prevParams => {
      const next = new URLSearchParams(prevParams)
      serializeCursor(newCursor, next)
      return next
    })
  }

  const onSelectTab = (tab: FindingState) => {
    setParams(prevParams => {
      const next = new URLSearchParams(prevParams)
      next.set('state', tab)
      serializeCursor(null, next)
      return next
    })
  }

  const onFilterQueryChange = (query: string) => {
    setParams(prevParams => {
      const next = new URLSearchParams(prevParams)
      if (query) {
        next.set('query', query)
      } else {
        next.delete('query')
      }
      serializeCursor(null, next)
      return next
    })
  }

  return {
    cursor,
    selectedTab,
    filterQuery,
    onCursorChange,
    onSelectTab,
    onFilterQueryChange,
  }
}
