import {Filter, type FilterQuery} from '@github-ui/filter'
import {useMemo} from 'react'
import {useSyncedState} from '@primer/react'

import {
  StateFilterProvider,
  SeverityFilterProvider,
  CategoryFilterProvider,
  LanguageFilterProvider,
} from '../filter-providers/repo-static-providers'
import {DEFAULT_FINDING_STATE} from '../types/rule-finding'

export const DEFAULT_QUERY = `is:${DEFAULT_FINDING_STATE}`

export interface RuleListFilterProps {
  query: string
  onQueryChange: (query: string) => void
}

export function RuleListFilter({query, onQueryChange}: RuleListFilterProps) {
  const [filterValue, setFilterValue] = useSyncedState(query)

  const providers = useMemo(
    () => [
      new StateFilterProvider(),
      new SeverityFilterProvider(),
      new CategoryFilterProvider(),
      new LanguageFilterProvider(),
    ],
    [],
  )

  const handleSubmit = (request: FilterQuery) => {
    onQueryChange(request.raw)
  }

  return (
    <Filter
      id="rule-list-filter"
      label="Filter rules"
      providers={providers}
      filterValue={filterValue}
      onChange={setFilterValue}
      onSubmit={handleSubmit}
    />
  )
}
