import {Blankslate, DataTable, Table, type Column, type ObjectPaths} from '@primer/react/experimental'
import type {OrgRepo} from '../types/org-repo'
import {RelativeTime, Truncate, Link} from '@primer/react'
import {number as formatNumber} from '@github-ui/formatters'
import {RepoIcon} from '@primer/octicons-react'
import {codeQualityIndexPath} from '@github-ui/paths'
import {MetricProgressBar} from './MetricProgressBar'
import styles from './OrgReposTable.module.css'
import {gradeToNumber, gradeToText} from '../types/grade'
import {addQualifierToQuery, getQualifierFromQuery} from '../utils/filters'
import {useFilterParams} from '../hooks/use-filter-params'

// This is a mapping from each OrgRepo property name to its corresponding sort: qualifier, e.g. name maps to
// sort:repository-name-asc, so this should contain repository-name.
const columnIdToSortType: Record<keyof OrgRepo, string | undefined> = {
  name: 'repository-name',
  maintainabilityGrade: 'maintainability',
  reliabilityGrade: 'reliability',
  aiFindingsCount: 'ai-findings-count',
  standardFindingsCount: 'standard-findings-count',
  lastActiveAt: 'last-activity',
  id: undefined,
}

type SortProps = {
  sortColumn: keyof OrgRepo
  sortDirection: 'ASC' | 'DESC'
}

// This is used to convert the sort qualifier (e.g. sort:repository-name-asc) into the props needed by DataTable
const sortValueToSortProps: Record<string, SortProps> = Object.entries(columnIdToSortType).reduce(
  (acc, [columnId, sortType]) => {
    if (sortType) {
      acc[`${sortType}-asc`] = {sortColumn: columnId as keyof OrgRepo, sortDirection: 'ASC'}
      acc[`${sortType}-desc`] = {sortColumn: columnId as keyof OrgRepo, sortDirection: 'DESC'}
    }
    return acc
  },
  {} as Record<string, SortProps>,
)

// The default sort function does not handle undefined and 0 values as distinct values, so this custom sort function
// treats undefined as -1 to ensure it is always sorted before 0.
const sortCount =
  (field: keyof Pick<OrgRepo, 'standardFindingsCount' | 'aiFindingsCount'>) => (a: OrgRepo, b: OrgRepo) => {
    const aValue = a[field] ?? -1
    const bValue = b[field] ?? -1
    if (aValue === bValue) {
      return 0
    }
    return aValue > bValue ? 1 : -1
  }

// The default sort function does not handle undefined values as distinct values, so this custom sort function
// treats undefined as Infinity to ensure it is always sorted before defined grades (undefined > excellent to match
// the behavior of Turboquality).
const sortGrade =
  (field: keyof Pick<OrgRepo, 'maintainabilityGrade' | 'reliabilityGrade'>) => (a: OrgRepo, b: OrgRepo) => {
    const aValue = a[field] !== undefined ? gradeToNumber[a[field]] : Infinity
    const bValue = b[field] !== undefined ? gradeToNumber[b[field]] : Infinity
    if (aValue === bValue) {
      return 0
    }
    return aValue < bValue ? 1 : -1
  }

export type OrgReposTableProps = {
  organizationLogin: string
  repos: OrgRepo[]
  isLoading: boolean
}

export function OrgReposTable({organizationLogin, repos, isLoading}: OrgReposTableProps) {
  const {query, onQueryChange, manipulateQuery} = useFilterParams()
  const sortValue = getQualifierFromQuery(query, 'sort')[0] || ''
  const sortProps = sortValueToSortProps[sortValue]

  const handleToggleSort = (columnId: ObjectPaths<OrgRepo> | string | number, direction: 'ASC' | 'DESC') => {
    const sortType = columnIdToSortType[columnId as keyof OrgRepo]

    if (!sortType) {
      return
    }

    manipulateQuery(newQuery => addQualifierToQuery(newQuery, 'sort', `${sortType}-${direction.toLowerCase()}`))
  }

  const handleClearQuery = () => {
    onQueryChange('')
  }

  const columns: Array<Column<OrgRepo>> = [
    {
      header: 'Repository',
      field: 'name',
      minWidth: 160,
      width: 'growCollapse',
      rowHeader: true,
      renderCell: cellData => (
        <a href={codeQualityIndexPath({owner: organizationLogin, repo: cellData.name})} className="width-full">
          <Truncate title={cellData.name} inline maxWidth="100%">
            {cellData.name}
          </Truncate>
        </a>
      ),
      sortBy: 'alphanumeric',
    },
    {
      header: 'Maintainability',
      field: 'maintainabilityGrade',
      renderCell: cellData =>
        cellData.maintainabilityGrade !== undefined && (
          <div className={styles.ProgressBarCell}>
            <MetricProgressBar grade={cellData.maintainabilityGrade} />
            <span>{gradeToText[cellData.maintainabilityGrade]}</span>
          </div>
        ),
      sortBy: sortGrade('maintainabilityGrade'),
      width: 200,
    },
    {
      header: 'Reliability',
      field: 'reliabilityGrade',
      renderCell: cellData =>
        cellData.reliabilityGrade !== undefined && (
          <div className={styles.ProgressBarCell}>
            <MetricProgressBar grade={cellData.reliabilityGrade} />
            <span>{gradeToText[cellData.reliabilityGrade]}</span>
          </div>
        ),
      sortBy: sortGrade('reliabilityGrade'),
      width: 200,
    },
    {
      header: 'AI Findings',
      field: 'aiFindingsCount',
      align: 'end',
      renderCell: cellData => (cellData.aiFindingsCount !== undefined ? formatNumber(cellData.aiFindingsCount) : null),
      sortBy: sortCount('aiFindingsCount'),
      width: 120,
    },
    {
      header: 'Standard Findings',
      field: 'standardFindingsCount',
      align: 'end',
      renderCell: cellData =>
        cellData.standardFindingsCount !== undefined ? (
          formatNumber(cellData.standardFindingsCount)
        ) : (
          <span className="color-fg-muted">Not Supported</span>
        ),
      sortBy: sortCount('standardFindingsCount'),
      width: 160,
    },
    {
      header: 'Last Activity',
      field: 'lastActiveAt',
      renderCell: cellData => <RelativeTime date={new Date(cellData.lastActiveAt)} />,
      sortBy: 'datetime',
      width: 160,
    },
  ]

  if (isLoading) {
    return (
      <Table.Container>
        <Table.Skeleton rows={10} columns={columns} />
      </Table.Container>
    )
  }

  if (repos.length === 0) {
    return (
      <Blankslate>
        <Blankslate.Visual>
          <RepoIcon size="medium" />
        </Blankslate.Visual>
        <Blankslate.Heading>No repositories found.</Blankslate.Heading>
        <Blankslate.Description>
          {query.trim() === '' ? (
            <>Only repositories where you have access to view code quality findings are shown on this page.</>
          ) : (
            <>
              Try{' '}
              <Link inline onClick={handleClearQuery} as="button">
                clearing current search filters
              </Link>
              .
            </>
          )}
        </Blankslate.Description>
      </Blankslate>
    )
  }

  return (
    <Table.Container>
      <DataTable<OrgRepo>
        columns={columns}
        data={repos}
        // Default sort order is lastActiveAt DESC
        initialSortColumn={sortProps?.sortColumn ?? 'lastActiveAt'}
        initialSortDirection={sortProps?.sortDirection ?? 'DESC'}
        onToggleSort={handleToggleSort}
        externalSorting
      />
    </Table.Container>
  )
}
