import DataCard from '@github-ui/data-card'
import {codeQualityAIFindingsPath} from '@github-ui/paths'
import {Link} from '@primer/react'
import styles from './RecentSuggestionsCard.module.css'

export interface RecentSuggestionsCardProps {
  owner: string
  repo: string
  count: number
}

export function RecentSuggestionsCard({owner, repo, count}: RecentSuggestionsCardProps) {
  return (
    <DataCard className={styles.Card}>
      <h3 className={styles.Heading}>Suggestions powered by AI</h3>
      <p className={styles.Count}>
        <span>{count}</span> <span>{count === 1 ? 'Finding' : 'Findings'}</span>
      </p>

      <DataCard.Description className={styles.Description}>
        <span>
          <Link inline href={codeQualityAIFindingsPath({owner, repo})}>
            Take action
          </Link>{' '}
          on suggestions on recently changed files of your codebase.
        </span>
      </DataCard.Description>
    </DataCard>
  )
}
