import {Label} from '@primer/react'
import styles from './CopilotAutofixState.module.css'
import {CopilotIcon} from '@primer/octicons-react'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export function CopilotAutofixState({message}: {message: string}) {
  const showPageImprovementsFFEnabled = isFeatureEnabled('code_quality_backlog_rule_show')

  return (
    <div className={showPageImprovementsFFEnabled ? styles.stateContainer : styles.legacyStateContainer}>
      <div>
        <CopilotIcon />
      </div>
      Copilot Autofix
      <Label size="small" variant="secondary">
        AI
      </Label>
      <div className={`color-fg-muted`}>{message}</div>
    </div>
  )
}
