import {IconButton} from '@primer/react'
import {useTheme} from '@primer/styled-react'
import {XIcon} from '@primer/octicons-react'
import {useState} from 'react'
import styles from './CodeQualityBannerWithImage.module.css'
import {BANNER_CONFIGS, type BannerVariant} from './banner-configs'

export interface CodeQualityBannerWithImageProps {
  title: string
  description: string | React.ReactNode
  mainAction: React.ReactNode
  secondaryAction?: React.ReactNode
  bannerVariant: BannerVariant
}

const CodeQualityBannerWithImage = ({
  title,
  description,
  mainAction,
  secondaryAction,
  bannerVariant,
}: CodeQualityBannerWithImageProps) => {
  const bannerConfig = BANNER_CONFIGS[bannerVariant]
  const {resolvedColorScheme} = useTheme()

  const [isVisible, setIsVisible] = useState(() => {
    if (typeof window !== 'undefined' && bannerConfig.localStorageKey) {
      const wasDismissed = localStorage.getItem(bannerConfig.localStorageKey)
      return !wasDismissed
    }
    return true
  })

  const isDark = resolvedColorScheme === 'dark'

  const desktopImage = isDark ? bannerConfig.images.dark : bannerConfig.images.light
  const mobileImage = isDark ? bannerConfig.images.darkMobile : bannerConfig.images.lightMobile

  const handleClose = () => {
    setIsVisible(false)
    if (typeof window !== 'undefined' && bannerConfig.localStorageKey) {
      localStorage.setItem(bannerConfig.localStorageKey, 'true')
    }
  }

  if (!isVisible) {
    return null
  }

  return (
    <div className={styles.banner}>
      <div
        className={styles.contentImage}
        style={
          {
            '--bg-image-desktop': `url(${desktopImage})`,
            '--bg-image-mobile': `url(${mobileImage})`,
          } as React.CSSProperties
        }
      />
      <div className={styles.contentSection}>
        <h2 className={styles.bannerTitle}>{title}</h2>
        <p className={styles.bannerDescription}>{description}</p>
        <div className={styles.actions}>
          {mainAction}
          {secondaryAction}
        </div>
      </div>
      {bannerConfig.localStorageKey ? (
        <div className={styles.closeButtonSection}>
          <IconButton aria-label="Close banner" icon={XIcon} variant="default" size="small" onClick={handleClose} />
        </div>
      ) : null}
    </div>
  )
}

export default CodeQualityBannerWithImage
