import {useState, useCallback} from 'react'
import type {SuggestedFixFile} from '../types/suggested-fix'
import {RecentActivityCommitFixDialog} from './RecentActivityCommitFixDialog'
import {CodeQualityCommitFixButton} from './CodeQualityCommitFixButton'

export interface RecentActivityCommitFixButtonProps {
  suggestedFixFiles: SuggestedFixFile[]
  owner: string
  repo: string
  defaultBranch: string
  branchListCacheKey: string
  onFixWithCopilot: () => void
  isPrBeingCreated: boolean
  disabled?: boolean
  testId?: string
}

export function RecentActivityCommitFixButton({
  suggestedFixFiles,
  owner,
  repo,
  defaultBranch,
  branchListCacheKey,
  onFixWithCopilot,
  isPrBeingCreated,
  disabled,
  testId,
}: RecentActivityCommitFixButtonProps) {
  const [showCreateBranchDialog, setShowCreateBranchDialog] = useState(false)

  const handleClose = useCallback(() => {
    setShowCreateBranchDialog(false)
  }, [])

  return (
    <>
      <CodeQualityCommitFixButton
        isPrBeingCreated={isPrBeingCreated}
        onFixWithCopilot={onFixWithCopilot}
        setShowCreateBranchDialog={setShowCreateBranchDialog}
        disabled={disabled}
        testId={testId}
      />

      {showCreateBranchDialog && (
        <RecentActivityCommitFixDialog
          suggestedFixFiles={suggestedFixFiles}
          owner={owner}
          repo={repo}
          defaultBranch={defaultBranch}
          branchListCacheKey={branchListCacheKey}
          onClose={handleClose}
        />
      )}
    </>
  )
}
