import {useNavigation} from '@github-ui/react-router'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {Heading} from '@primer/react'
import {orgCodeQualityIndexRoute} from './org-code-quality-index-route'

import {CountsBubbleChart} from '../components/CountsBubbleChart'
import {OrgFilter} from '../components/OrgFilter'
import {OrgReposTable} from '../components/OrgReposTable'
import {OrgReposPagination} from '../components/OrgReposPagination'
import {OrgNoCodeQualityReposBlankslate} from '../components/OrgNoCodeQualityReposBlankslate'
import {useFilterParams} from '../hooks/use-filter-params'

export function OrgCodeQualityIndex() {
  const payload = useRouteQuery(orgCodeQualityIndexRoute, 'mainQuery')
  const {organizationLogin, customPropertyNames, counts, repos, codeQualityDocsUrls, prevCursor, nextCursor} =
    payload.data
  const {state} = useNavigation()

  const {query} = useFilterParams()
  if (query.trim() === '' && counts.length === 0 && repos.length === 0) {
    return <OrgNoCodeQualityReposBlankslate docsUrls={codeQualityDocsUrls} />
  }

  return (
    <>
      <div className="d-flex flex-items-center flex-justify-between flex-wrap mb-1">
        <div className="d-flex flex-items-center gap-2">
          <Heading className="h3" as="h2">
            Code quality
          </Heading>
          <BetaLabel />
        </div>
      </div>
      <p className="fgColor-muted">Code quality insights across your organization.</p>
      <OrgFilter organizationLogin={organizationLogin} customPropertyNames={customPropertyNames} />
      <CountsBubbleChart counts={counts} />
      <OrgReposTable
        organizationLogin={organizationLogin}
        repos={repos}
        isLoading={payload.isFetching || state === 'loading'}
      />
      <OrgReposPagination prevCursor={prevCursor} nextCursor={nextCursor} />
    </>
  )
}
