import {mainQuery} from '@github-ui/react-core/future/main-query'
import {codeQualityAppBuilder} from '../config/app-builder'
import type {CodeQualityDocsUrls} from '../types/code-quality-docs-urls'

export type Language = {
  name: string
  color: string
}

export type RepoCodeQualitySettingsResponse = {
  owner: string
  repo: string
  isDefaultSetupEnabled: boolean
  isDefaultSetupEnabling: boolean
  isCodeQualityEnabled: boolean
  codeQualitySetupState: 'enabling' | 'updating' | null
  hasFailedUpdate?: boolean
  languages: Language[]
  defaultBranch: string
  nextScheduledRunAt: string | null
  runnerLabel: string | null
  aboutCodeQLDocsURL: string
  aboutActionsBillingDocsURL: string
  codeqlLanguagesDocumentationUrl: string
  codeQualityDocsUrls: CodeQualityDocsUrls
  hasMacOsRunner: boolean
  selectableLanguages: string[]
  selectedLanguages: string[]
  settingsEditable: boolean
  availableRunnerLabels: string[]
  onlyLabeledRunners: boolean
  runnerType: string
  recentActivityEnabled: boolean
  isEnablingAllowedByPolicy: boolean
  codeQualityWorkflowRunUrl?: string | null
}

export const repoCodeQualitySettingsRoute = codeQualityAppBuilder.createQueryRouteConfig(
  'repoCodeQualitySettingsRoute',
  {
    path: '/:owner/:repo/settings/code-quality',
    queries: [mainQuery<RepoCodeQualitySettingsResponse>()],
  },
)
