import {mainQuery} from '@github-ui/react-core/future/main-query'
import {codeQualityAppBuilder} from '../config/app-builder'
import type {OrgCount} from '../types/org-count'
import type {OrgRepo} from '../types/org-repo'
import type {CodeQualityDocsUrls} from '../types/code-quality-docs-urls'

export type OrgCodeQualityIndexResponse = {
  organizationLogin: string
  customPropertyNames: string[]
  counts: OrgCount[]
  repos: OrgRepo[]
  codeQualityDocsUrls: CodeQualityDocsUrls
  prevCursor?: string | null
  nextCursor?: string | null
}

export const orgCodeQualityIndexRoute = codeQualityAppBuilder.createQueryRouteConfig('orgCodeQualityIndexRoute', {
  path: '/orgs/:org/security/quality',
  queries: [
    mainQuery<OrgCodeQualityIndexResponse>({
      queryDeps: ({pathname, searchParams}) => ({
        pathname,
        searchParams: {
          query: searchParams.get('query') || '',
          before: searchParams.get('before') || null,
          after: searchParams.get('after') || null,
        },
      }),
    }),
  ],
})
