import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'

export type RuleFindingStateMutationRequest = {
  ruleId: string
  filePath: string
  state: string
}

export function useRuleFindingStateMutation(
  path: string,
): UseMutationResult<void, Error, RuleFindingStateMutationRequest> {
  return useMutation({
    mutationFn: request => {
      return fetchJson(path, {
        method: 'PATCH',
        defaultErrorMessage: 'Could not update finding state, please try again later.',
        body: {
          rule_id: request.ruleId,
          file_path: request.filePath,
          state: request.state,
        },
      })
    },
  })
}
