import {useMemo, useState} from 'react'
import {clsx} from 'clsx'
import type {SuggestedFixDiffEntry} from '../types/suggested-fix'
import {getLineNumberWidth} from '@github-ui/diffs/diff-line-helpers'
import {hasHiddenUnicodeCharacters} from '@github-ui/hidden-unicode-banner/utils'
import {HiddenUnicodeBanner} from '@github-ui/hidden-unicode-banner/HiddenUnicodeBanner'
import {normalizedStartColumn} from '../utils/normalized-start-column'
import {SplitDiffTable} from './diff/SplitDiffTable'
import {SplitDiffLines} from './diff/SplitDiffLines'

import styles from './CodeQualityFileFrame.module.css'

export interface CodeQualityDiffProps {
  diffEntry: SuggestedFixDiffEntry

  startLine: number
  endLine: number
  startColumn: number
  endColumn: number
  borderVariant?: 'rounded' | 'none'
}

export function CodeQualityDiff({
  diffEntry,
  startLine,
  endLine,
  startColumn,
  endColumn,
  borderVariant = 'rounded',
}: CodeQualityDiffProps) {
  const [showHiddenUnicodeCharacters, setShowHiddenUnicodeCharacters] = useState(false)

  const shownDiffLines = useMemo(() => diffEntry.diffLines.filter(line => line.type !== 'HUNK'), [diffEntry.diffLines])

  const diffHasHiddenUnicodeCharacters = useMemo(
    () => shownDiffLines.some(line => hasHiddenUnicodeCharacters(line.text)),
    [shownDiffLines],
  )

  const borderClasses = borderVariant === 'rounded' ? 'border rounded-2 overflow-hidden' : ''

  const lineNumberWidth = getLineNumberWidth(shownDiffLines)
  return (
    <div className={clsx(borderClasses, 'position-relative')}>
      {diffHasHiddenUnicodeCharacters && (
        <HiddenUnicodeBanner
          isShown={showHiddenUnicodeCharacters}
          toggleShowHiddenCharacters={() => setShowHiddenUnicodeCharacters(oldShow => !oldShow)}
        />
      )}
      <table
        className={clsx(
          'tab-size',
          'width-full',
          'js-highlight-code-snippet-columns',
          styles.tableLayoutFixed,
          styles.compact,
        )}
        role="grid"
        style={{
          '--line-number-cell-width': `${lineNumberWidth}px`,
          '--line-number-cell-width-unified': `${parseFloat(lineNumberWidth) * 2}px`,
        }}
        data-start-line={startLine}
        data-end-line={endLine}
        data-start-column={normalizedStartColumn(startColumn, endColumn)}
        data-end-column={endColumn}
      >
        <SplitDiffTable lineWidth={lineNumberWidth}>
          <SplitDiffLines
            diffLines={shownDiffLines}
            diffHasHiddenUnicodeCharacters={diffHasHiddenUnicodeCharacters}
            showHiddenUnicode={showHiddenUnicodeCharacters}
          />
        </SplitDiffTable>
      </table>
    </div>
  )
}
