import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {Heading, Link, Button, Stack} from '@primer/react'
import {useLoaderData} from '@github-ui/react-router'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {RecentActivityFindings} from '../components/RecentActivityFindings'
import styles from './RepoCodeQualityRecentActivity.module.css'
import {BannerProvider} from '@github-ui/role-assignments/banner-provider'
import CodeQualityBannerWithImage from '../components/CodeQualityBannerWithImage'
import {codeQualityIndexPath} from '@github-ui/paths'

export function RepoCodeQualityRecentActivity() {
  const {route} = useLoaderData()
  const payload = useRouteQuery(route, 'mainQuery')
  const {
    owner,
    repo,
    defaultBranch,
    fileFindings,
    copilotSWEAgentEnabled,
    copilotCodingAgentDocsUrl,
    codeQualityDocsUrls,
    branchListCacheKey,
    hasRepoWriteAccess,
  } = payload.data

  return (
    <BannerProvider>
      <Stack gap="none">
        <div className="d-flex flex-items-center gap-2 mb-1">
          <Heading as="h2" className="h3">
            AI findings
          </Heading>
          <BetaLabel />
        </div>
        <p className={styles.description}>
          Fix code quality issues in your recently-changed files with the help of suggestions from AI. To see findings
          from a full scan of your codebase see{' '}
          <Link inline href={codeQualityIndexPath({owner, repo})}>
            Standard findings
          </Link>
          .
        </p>
      </Stack>
      <CodeQualityBannerWithImage
        bannerVariant="AISuggestions"
        title="Suggestions powered by AI"
        description="Focus on actionable improvements in the code you're actively working with—view suggestions from AI to improve your most recently changed files on the default branch."
        mainAction={
          <Button size="small" as="a" href={codeQualityDocsUrls.improve}>
            Learn more
          </Button>
        }
      />
      <RecentActivityFindings
        owner={owner}
        repo={repo}
        branch={defaultBranch}
        initialFiles={fileFindings}
        copilotSWEAgentEnabled={copilotSWEAgentEnabled}
        copilotCodingAgentDocsUrl={copilotCodingAgentDocsUrl}
        codeQualityDocsUrls={codeQualityDocsUrls}
        branchListCacheKey={branchListCacheKey}
        hasRepoWriteAccess={hasRepoWriteAccess}
      />
    </BannerProvider>
  )
}
