import {mainQuery} from '@github-ui/react-core/future/main-query'
import {codeQualityAppBuilder} from '../config/app-builder'
import type {AiFileFindings} from '../types/ai-findings'
import type {CodeQualityDocsUrls} from '../types/code-quality-docs-urls'

export type RepoCodeQualityRecentActivityResponse = {
  owner: string
  repo: string
  defaultBranch: string
  fileFindings: AiFileFindings[]
  copilotSWEAgentEnabled: boolean
  copilotCodingAgentDocsUrl: string
  codeQualityDocsUrls: CodeQualityDocsUrls
  branchListCacheKey: string
  hasRepoWriteAccess: boolean
}

export const repoCodeQualityAIFindingsRoute = codeQualityAppBuilder.createQueryRouteConfig(
  'repoCodeQualityAIFindingsRoute',
  {
    path: '/:owner/:repo/security/quality/ai-findings',
    queries: [mainQuery<RepoCodeQualityRecentActivityResponse>()],
  },
)
