import {useCallback, useState, useEffect} from 'react'
import {LanguageSelection} from '@github-ui/code-scanning-shared/components/LanguageSelection'
import {RunnerType, type RunnerLabelType} from '@github-ui/code-scanning-shared/components/RunnerType'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {repoCodeQualitySettingsRoute, type RepoCodeQualitySettingsResponse} from './repo-code-quality-settings-route'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {Heading, Link, Button, BranchName, RelativeTime, Banner, Spinner} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import styles from './RepoCodeQualitySettings.module.css'
import {DotFillIcon, InfoIcon} from '@primer/octicons-react'
import {repoSettingsSecurityAnalysisPath} from '@github-ui/paths'
import {useToggleCodeQualityMutation} from '../hooks/use-toggle-code-quality-mutation'
import {useUpdateCodeQualitySettingsMutation} from '../hooks/use-update-code-quality-settings-mutation'
import {useQueryClient} from '@github-ui/react-query'
import type {QueryClient} from '@github-ui/react-query'
import CodeQualityBannerWithImage from '../components/CodeQualityBannerWithImage'
import {MarkdownRenderer} from '@github-ui/copilot-markdown'

function getSubmitButtonText(codeQualitySetupState: RepoCodeQualitySettingsResponse['codeQualitySetupState']): string {
  if (!codeQualitySetupState) return 'Save changes'
  return codeQualitySetupState === 'enabling' ? 'Setting up' : 'Saving'
}

function renderSettingsSavedDescription(workflowRunUrl: string | null | undefined) {
  const defaultMessage = 'Code Quality is applying your new settings.'
  if (!workflowRunUrl) {
    return defaultMessage
  }

  return <MarkdownRenderer markdown={`${defaultMessage} [View workflow run](${workflowRunUrl}).`} />
}

function renderSetupInProgressDescription(workflowRunUrl: string | null | undefined) {
  const defaultMessage = 'Code Quality is scanning your repository for the first time. This may take several minutes.'
  if (!workflowRunUrl) {
    return defaultMessage
  }

  return <MarkdownRenderer markdown={`${defaultMessage} [View workflow run](${workflowRunUrl}).`} />
}

function renderUpdateInProgressDescription(workflowRunUrl: string | null | undefined) {
  const defaultMessage = 'Code Quality is applying changes. This may take several minutes.'
  if (!workflowRunUrl) {
    return defaultMessage
  }

  return (
    <>
      {defaultMessage}{' '}
      <Link href={workflowRunUrl} target="_blank" rel="noopener noreferrer">
        View workflow run
      </Link>
      .
    </>
  )
}

function renderSetupFailedDescription(workflowRunUrl: string | null | undefined) {
  const defaultMessage = 'The setup or update was unable to complete.'
  if (!workflowRunUrl) {
    return `${defaultMessage} Review the workflow logs.`
  }

  return (
    <>
      {defaultMessage}{' '}
      <Link href={workflowRunUrl} target="_blank" rel="noopener noreferrer">
        Review the workflow logs
      </Link>
      .
    </>
  )
}

type RunnerLabelUpdateSuccess = {
  runnerLabel: string | null
  runnerType: RunnerLabelType
}

function isRunnerSelectionValid(runnerType: RunnerLabelType, runnerLabel: string | null) {
  return runnerType === 'standard' || Boolean(runnerLabel)
}

function renderRunnerLabelSuccessDescription(state: RunnerLabelUpdateSuccess): React.ReactNode {
  if (state.runnerType === 'labeled' && state.runnerLabel) {
    return (
      <>
        The runner label <span className="text-bold">{state.runnerLabel}</span> will now be used for future Code Quality
        scans.
      </>
    )
  }

  return 'Code Quality will now use the standard GitHub runner for future scans.'
}

export function RepoCodeQualitySettings() {
  const mainQuery = useRouteQuery(repoCodeQualitySettingsRoute, 'mainQuery', {
    refetchInterval: query => {
      // When the data comes from the server it gets wrapped into a meta + payload structure,
      // but when we want to poll we are not passing in a wrapped object but the payload itself.
      // So we need to handle both cases here.
      type WrappedResponse = {
        meta: {title: string}
        payload: RepoCodeQualitySettingsResponse
      }

      const rawData = query.state.data as RepoCodeQualitySettingsResponse | WrappedResponse | undefined

      // Handle both direct response and wrapped response formats
      const data = rawData && 'payload' in rawData ? rawData.payload : rawData
      const shouldPoll = Boolean(data?.codeQualitySetupState)
      const interval = shouldPoll ? 10000 : false
      return interval
    },
  })

  const [serverSettings, setServerSettings] = useState<RepoCodeQualitySettingsResponse>(mainQuery.data)

  // Track current languages separately so the user can stage edits while polling happens.
  const [currentSelectedLanguages, setCurrentSelectedLanguages] = useState<Set<string>>(
    () => new Set(serverSettings.selectedLanguages ?? []),
  )

  const [runnerLabel, setRunnerLabel] = useState<string | null>(serverSettings.runnerLabel ?? null)
  const [runnerType, setRunnerType] = useState<RunnerLabelType>(serverSettings.runnerType as RunnerLabelType)
  const [runnerLabelUpdateSuccess, setRunnerLabelUpdateSuccess] = useState<RunnerLabelUpdateSuccess | null>(null)
  const [runnerLabelValid, setRunnerLabelValid] = useState<boolean>(() =>
    isRunnerSelectionValid(serverSettings.runnerType as RunnerLabelType, serverSettings.runnerLabel ?? null),
  )

  const codeQualitySetupState = serverSettings.codeQualitySetupState ?? null
  const isSetupOrUpdateInProgress = Boolean(codeQualitySetupState)

  useEffect(() => {
    if (mainQuery.data) {
      const isSetupOrUpdateInProgressForNewData = Boolean(mainQuery.data.codeQualitySetupState)

      // The reason we are overriding this lint rule is that useEffect is meant to sync state with props.
      // The main concern with calling setState in useEffect is the risk of infinite re-renders,
      // Here, we prevent infinite loops by only updating the state if we get
      // a successful new response from the server.
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setServerSettings(mainQuery.data)
      // Only update local state if not in the middle of an update to presereve user's requested changes
      // while update is in progress.
      if (!isSetupOrUpdateInProgressForNewData) {
        setRunnerLabel(mainQuery.data.runnerLabel ?? null)
        setRunnerType(mainQuery.data.runnerType as RunnerLabelType)
        setCurrentSelectedLanguages(new Set(mainQuery.data.selectedLanguages ?? []))
        const nextRunnerLabel = mainQuery.data.runnerLabel ?? null
        setRunnerLabelValid(isRunnerSelectionValid(mainQuery.data.runnerType as RunnerLabelType, nextRunnerLabel))
      }
    }
  }, [mainQuery.data])

  // Runner state and UI are managed by RunnerType component. Code Quality only
  // needs to know whether the chosen runner selection is valid for submit.

  const handleRunnerChange = useCallback((change: {runnerType: RunnerLabelType; runnerLabel: string}) => {
    const valid = isRunnerSelectionValid(change.runnerType, change.runnerLabel)
    setRunnerLabel(change.runnerLabel)
    setRunnerType(change.runnerType)
    setRunnerLabelValid(valid)
  }, [])

  const hasRunnerLabelChanges = () => {
    if (!serverSettings) return false
    const changed = serverSettings.runnerLabel !== runnerLabel || serverSettings.runnerType !== runnerType
    return changed
  }

  const hasLanguageChanges = () => {
    const currentLanguagesArray = Array.from(currentSelectedLanguages).sort()
    const originalLanguages = serverSettings.selectedLanguages.slice().sort()
    return JSON.stringify(currentLanguagesArray) !== JSON.stringify(originalLanguages)
  }

  const runnerSelectionChanged = hasRunnerLabelChanges()
  const languageSelectionChanged = hasLanguageChanges()

  const toggleCodeQuality = useToggleCodeQualityMutation()
  const updateSettings = useUpdateCodeQualitySettingsMutation()
  const queryClient = useQueryClient()

  // Reset mutation states when setup/update completes
  useEffect(() => {
    if (!isSetupOrUpdateInProgress) {
      // Reset toggle state if we were in first-time setup and it just completed
      if (toggleCodeQuality.isSuccess && serverSettings.isCodeQualityEnabled) {
        toggleCodeQuality.reset()
      }

      // Reset update settings state when any update completes to avoid stale success banners
      if (updateSettings.isSuccess) {
        updateSettings.reset()
      }
    }
  }, [isSetupOrUpdateInProgress, serverSettings.isCodeQualityEnabled, toggleCodeQuality, updateSettings])

  // This bool acts as an extra check to stop showing the updated runner label banner
  // if the user has made further changes since the last update.
  const shouldShowRunnerLabelUpdateSuccess = Boolean(
    runnerLabelUpdateSuccess && !languageSelectionChanged && !runnerSelectionChanged,
  )
  const runnerLabelSuccessState = shouldShowRunnerLabelUpdateSuccess ? runnerLabelUpdateSuccess : null

  return (
    <>
      <div className="d-flex flex-items-center flex-justify-between tmp-mb-0">
        <div className="d-flex flex-1 flex-items-center">
          <div className="d-flex flex-1 gap-2 flex-items-center">
            <Heading as="h2">Code quality</Heading>
            <BetaLabel />
          </div>
          {serverSettings.isCodeQualityEnabled && (
            <Button
              variant="danger"
              onClick={() =>
                toggleCodeQuality.mutate(
                  {owner: serverSettings.owner, repo: serverSettings.repo, enabled: false},
                  {
                    onSuccess: updatedSettings => {
                      setServerSettings(updatedSettings)
                    },
                  },
                )
              }
              disabled={
                toggleCodeQuality.isPending || isSetupOrUpdateInProgress || !serverSettings.isEnablingAllowedByPolicy
              }
            >
              Disable
            </Button>
          )}
        </div>
      </div>

      {toggleCodeQuality.isError && !serverSettings.isCodeQualityEnabled && (
        <Banner title="Error" description={toggleCodeQuality.error.message} variant="critical" />
      )}

      {pageContent(
        serverSettings,
        setServerSettings,
        toggleCodeQuality,
        updateSettings,
        currentSelectedLanguages,
        setCurrentSelectedLanguages,
        runnerLabel,
        runnerType,
        handleRunnerChange,
        runnerLabelValid,
        queryClient,
        mainQuery.queryKey,
        runnerSelectionChanged,
        languageSelectionChanged,
        setRunnerLabelUpdateSuccess,
        runnerLabelSuccessState,
      )}
    </>
  )
}

function pageContent(
  settings: RepoCodeQualitySettingsResponse,
  setSettings: (settings: RepoCodeQualitySettingsResponse) => void,
  toggleCodeQuality: ReturnType<typeof useToggleCodeQualityMutation>,
  updateSettings: ReturnType<typeof useUpdateCodeQualitySettingsMutation>,
  currentSelectedLanguages: Set<string>,
  setCurrentSelectedLanguages: (languages: Set<string>) => void,
  runnerLabel: string | null,
  runnerType: RunnerLabelType,
  handleRunnerChange: (change: {runnerType: RunnerLabelType; runnerLabel: string}) => void,
  isSubmittable: boolean,
  queryClient: QueryClient,
  mainQueryQueryKey: readonly unknown[],
  runnerLabelChanged: boolean,
  languagesChanged: boolean,
  setRunnerLabelUpdateSuccess: (state: RunnerLabelUpdateSuccess | null) => void,
  runnerLabelSuccessState: RunnerLabelUpdateSuccess | null,
) {
  const isSetupOrUpdateInProgress = Boolean(settings.codeQualitySetupState)

  if (!settings.settingsEditable && isSetupOrUpdateInProgress) {
    return (
      <Blankslate border>
        <Blankslate.Heading>Default setup settings for your repository are currently being applied.</Blankslate.Heading>
        <Blankslate.Description>Please check back later.</Blankslate.Description>
      </Blankslate>
    )
  }
  if (
    !settings.isCodeQualityEnabled &&
    !(toggleCodeQuality.isSuccess && settings.codeQualitySetupState === 'enabling')
  ) {
    return (
      <CodeQualityBannerWithImage
        bannerVariant="enablement"
        title="Build resilient code, at scale"
        description={
          <span className={styles.leftText}>
            Ensure your codebases are reliable, maintainable, and efficient by proactively scanning for best practices,
            reducing bugs, improving readability, and enabling easier testing, collaboration, and scalability. Enabling
            this feature will incur charges in{' '}
            <a href="https://docs.github.com/en/billing/concepts/product-billing/github-actions">action minutes.</a>
          </span>
        }
        mainAction={
          !settings.isEnablingAllowedByPolicy ? (
            <div className="mt-1 text-small color-fg-muted">
              An organization or enterprise policy prevents changing the Code Quality setting.
            </div>
          ) : settings.isDefaultSetupEnabled || settings.settingsEditable ? (
            <Button
              variant="primary"
              size="small"
              onClick={() =>
                toggleCodeQuality.mutate(
                  {owner: settings.owner, repo: settings.repo, enabled: true},
                  {
                    onSuccess: updatedSettings => {
                      if (updatedSettings.selectableLanguages) {
                        // If the user is enabling Code Quality, initially we are scanning all available languages.
                        // This block sets the current selected languages to all selectable languages until the initial scan
                        // has completed, it then updates to the languages successfully scanned in the configuration.
                        // This behavior will change when we have UI to select languages before enabling Code Quality.
                        // This is tracked in: https://github.com/github/code-scanning/issues/20496
                        setCurrentSelectedLanguages(new Set(updatedSettings.selectableLanguages ?? []))
                      }
                      setSettings(updatedSettings)
                      queryClient.setQueryData(mainQueryQueryKey, updatedSettings)
                    },
                  },
                )
              }
              disabled={toggleCodeQuality.isPending}
            >
              Enable code quality
            </Button>
          ) : (
            <div className="mt-1 text-small color-fg-muted">
              You don&apos;t have a default setup for CodeQL.{' '}
              <Link
                href={repoSettingsSecurityAnalysisPath({repo: {ownerLogin: settings.owner, name: settings.repo}})}
                inline
              >
                Enable it here.
              </Link>
            </div>
          )
        }
        secondaryAction={
          settings.isDefaultSetupEnabled || settings.settingsEditable ? (
            <Link href={settings.codeQualityDocsUrls.enable}>Learn more</Link>
          ) : null
        }
      />
    )
  }

  return (
    <form
      onSubmit={async event => {
        event.preventDefault()
        const runnerOnlyChange = runnerLabelChanged && !languagesChanged
        setRunnerLabelUpdateSuccess(null)
        updateSettings.mutate(
          {
            owner: settings.owner,
            repo: settings.repo,
            languages: Array.from(currentSelectedLanguages),
            runnerLabel,
            runnerType,
          },
          {
            onSuccess: updatedSettings => {
              const isSetupOrUpdateInProgressForUpdatedSettings = Boolean(updatedSettings.codeQualitySetupState)

              setSettings(updatedSettings)
              // Update the mainQuery cache so that we can start polling when setup/update begins.
              queryClient.setQueryData(mainQueryQueryKey, updatedSettings)
              if (runnerOnlyChange && !isSetupOrUpdateInProgressForUpdatedSettings) {
                setRunnerLabelUpdateSuccess({
                  runnerLabel: updatedSettings.runnerLabel ?? null,
                  runnerType: updatedSettings.runnerType as RunnerLabelType,
                })
              } else {
                setRunnerLabelUpdateSuccess(null)
              }
            },
          },
        )
      }}
      className="tmp-mt-3"
      method="post"
    >
      <div className="color-fg-muted tmp-mb-3">
        Ensure your codebases are reliable, maintainable, and efficient by proactively scanning for best practices,
        reducing bugs, improving readability, and enabling easier testing, collaboration, and scalability.
      </div>

      {updateSettings.isSuccess && isSetupOrUpdateInProgress && (
        <Banner
          title="Code Quality settings saved"
          description={renderSettingsSavedDescription(settings.codeQualityWorkflowRunUrl)}
          variant="info"
        />
      )}

      {toggleCodeQuality.isSuccess && settings.codeQualitySetupState === 'enabling' && (
        <Banner
          title="Code Quality setup in progress"
          description={renderSetupInProgressDescription(settings.codeQualityWorkflowRunUrl)}
          variant="info"
        />
      )}

      {isSetupOrUpdateInProgress && !toggleCodeQuality.isSuccess && !updateSettings.isSuccess && (
        <Banner
          title={
            settings.codeQualitySetupState === 'enabling'
              ? 'Code Quality setup in progress'
              : 'Code Quality update in progress'
          }
          description={
            settings.codeQualitySetupState === 'enabling'
              ? renderSetupInProgressDescription(settings.codeQualityWorkflowRunUrl)
              : renderUpdateInProgressDescription(settings.codeQualityWorkflowRunUrl)
          }
          variant="info"
        />
      )}

      {settings.hasFailedUpdate === true && !isSetupOrUpdateInProgress && (
        <Banner
          title="Setup failed"
          description={renderSetupFailedDescription(settings.codeQualityWorkflowRunUrl)}
          variant="critical"
        />
      )}

      {updateSettings.isError && <Banner title="Error" description={updateSettings.error.message} variant="critical" />}

      {toggleCodeQuality.isError && (
        <Banner title="Error" description={toggleCodeQuality.error.message} variant="critical" />
      )}

      {runnerLabelSuccessState && (
        <Banner
          title="Runner label updated"
          description={renderRunnerLabelSuccessDescription(runnerLabelSuccessState)}
          variant="success"
        />
      )}
      {settings.settingsEditable ? (
        <div className="tmp-mt-3 tmp-mb-3">
          <LanguageSelection
            key={`languages-${JSON.stringify(settings.selectedLanguages?.slice().sort() ?? [])}`}
            description={
              settings.recentActivityEnabled
                ? 'AI will scan all languages present in the most recently changed files. For a full scan of the codebase by CodeQL, select one or more supported languages detected on the default branch.'
                : 'Select one or more languages detected on the default branch for CodeQL to scan.'
            }
            blankslateDescription={
              settings.recentActivityEnabled ? (
                <>
                  AI will scan all languages present in the most recently changed files. CodeQL will perform the first
                  full scan of the codebase when it detects{' '}
                  <Link href={settings.codeqlLanguagesDocumentationUrl} target="_blank" inline>
                    a supported language
                  </Link>{' '}
                  on the default branch.
                </>
              ) : (
                <>
                  CodeQL will automatically perform the first scan when it detects{' '}
                  <Link href={settings.codeqlLanguagesDocumentationUrl} target="_blank" inline>
                    a supported language
                  </Link>{' '}
                  on the default branch.
                </>
              )
            }
            hasMacOsRunner={settings.hasMacOsRunner}
            selectableLanguages={settings.selectableLanguages}
            selectedLanguages={Array.from(currentSelectedLanguages)}
            onChange={(newSelectedLanguages: string[]) => {
              setCurrentSelectedLanguages(new Set(newSelectedLanguages))
            }}
            hideCustomBuildInfo
            headingLevel="h3"
            additionalHeaderClasses="h3"
            disabled={isSetupOrUpdateInProgress}
          />
        </div>
      ) : (
        <div className="tmp-mb-3">
          <Heading as="h3" className="h3 mb-1">
            Languages
          </Heading>
          <div className={styles.settingsGroupContainer}>
            <div className={styles.settingLanguagesRow}>
              {settings.languages.map(language => (
                <div key={language.name} className="mb-1 text-bold">
                  <span style={{color: language.color}}>
                    {/* The DotFillIcon component does have a fill attribute, but it does not work. */}
                    <DotFillIcon />
                  </span>{' '}
                  {language.name}
                </div>
              ))}
            </div>
            {settings.languages.length === 0 ? (
              <div className={styles.settingDescriptionRow}>
                <span className="color-fg-muted">
                  CodeQL will automatically perform the first scan when it detects{' '}
                  <Link href={settings.aboutCodeQLDocsURL} target="_blank" inline>
                    a supported language
                  </Link>{' '}
                  on the default branch.
                </span>
              </div>
            ) : (
              <div className={styles.settingDescriptionRow}>
                <span className="text-small color-fg-muted">
                  These languages were auto-detected on the default branch of your repository.
                </span>
              </div>
            )}
          </div>
        </div>
      )}

      <div className="tmp-mb-3">
        <Heading as="h3" className="h3 mb-1">
          Scan settings
        </Heading>
        <div className={styles.settingsGroupContainer}>
          {settings.settingsEditable ? (
            <RunnerType
              onlyLabeledRunners={settings.onlyLabeledRunners}
              availableRunnerLabels={settings.availableRunnerLabels}
              runnerType={runnerType}
              runnerLabel={runnerLabel || ''}
              productName="Code Quality"
              disabled={isSetupOrUpdateInProgress}
              runnerLabelValidationDisabled
              onChange={handleRunnerChange}
            />
          ) : (
            <div className="Box-row d-flex gap-3 pl-0">
              <div className="mr-auto">
                <span className="text-bold d-block">Runner type</span>
                <span className="text-small color-fg-muted d-block">
                  This feature uses Action minutes, which have limited free minutes for different plans.{' '}
                  <Link href={settings.aboutActionsBillingDocsURL} target="_blank" inline>
                    Learn more about GitHub runners billing.
                  </Link>
                </span>
              </div>

              <span className="text-bold no-wrap">
                {settings.runnerLabel ? 'Labeled runner' : 'Standard GitHub runner'}
              </span>
            </div>
          )}
          <div className={styles.settingRowWithTopBorder}>
            <div className="mr-auto">
              <span className="text-bold d-block">Quality query suites</span>
              <span className="text-small color-fg-muted d-block">
                Set of code quality queries run in the analysis.
              </span>
            </div>

            <span className="text-bold no-wrap">Default</span>
          </div>
        </div>
      </div>

      <div className="tmp-mb-3">
        <Heading as="h3" className="h3 mb-1">
          Scan events
        </Heading>
        <div className={styles.settingsGroupContainer}>
          <div className={styles.settingRowWithNoBorder}>
            <div className="mr-auto">
              <span className="text-bold d-block">On push and pull requests to</span>
              <span className="text-small color-fg-muted d-block">
                These events will trigger a scan on the selected branch of your repository.
              </span>
            </div>

            <span className="text-small color-fg-muted text-right">
              <BranchName as="span">{settings.defaultBranch}</BranchName>
            </span>
          </div>
          <div className={styles.settingRowWithTopBorder}>
            <div className="mr-auto">
              <span className="text-bold d-block">On a weekly schedule</span>
              <span className="text-small color-fg-muted d-block">
                A scheduled analysis will run on the default branch of the repository within the selected time period.
              </span>
            </div>

            {settings.nextScheduledRunAt != null && (
              <span className="text-right">
                Next scan of <BranchName as="span">{settings.defaultBranch}</BranchName>{' '}
                <RelativeTime datetime={settings.nextScheduledRunAt} threshold="PT0S" hour="numeric" minute="numeric" />
              </span>
            )}
          </div>
        </div>
      </div>

      {!settings.settingsEditable && (
        <span className="text-small color-fg-muted">
          <InfoIcon className="mr-1" />
          These are your default settings for CodeQL. If you want to change them, please go to{' '}
          <Link
            href={repoSettingsSecurityAnalysisPath({repo: {ownerLogin: settings.owner, name: settings.repo}})}
            inline
          >
            code security settings
          </Link>
          .
        </span>
      )}

      {settings.settingsEditable && (
        <div>
          <Button
            disabled={updateSettings.isPending || !isSubmittable || isSetupOrUpdateInProgress}
            type="submit"
            variant="primary"
            leadingVisual={isSetupOrUpdateInProgress ? <Spinner size="small" /> : undefined}
          >
            {getSubmitButtonText(settings.codeQualitySetupState)}
          </Button>
        </div>
      )}
    </form>
  )
}
