import {FindingState} from '../types/rule-finding'
import {getQualifierFromQuery} from './filters'

export function getActiveStatesFromQuery(query: string): FindingState[] {
  const activeStateStrings = getQualifierFromQuery(query, 'is')

  return activeStateStrings
    .map(value => {
      if (value === FindingState.Open) return FindingState.Open
      if (value === FindingState.Dismissed) return FindingState.Dismissed
      return undefined
    })
    .filter((value): value is FindingState => value !== undefined)
}
