import {serializeCursor} from '@github-ui/code-scanning-shared/types/cursor'
import {useSearchParams} from '@github-ui/use-navigate'
import {useCallback} from 'react'
import {
  DEFAULT_SORT_FIELD,
  DEFAULT_SORT_DIRECTION,
  isSortField,
  isSortDirection,
  type RuleSortField,
  type RuleSortDirection,
} from '../types/rule-sort'

function parseSortField(params: URLSearchParams): RuleSortField {
  const raw = params.get('sort_field')
  return raw && isSortField(raw) ? raw : DEFAULT_SORT_FIELD
}

function parseSortDirection(params: URLSearchParams): RuleSortDirection {
  const raw = params.get('sort_direction')
  return raw && isSortDirection(raw) ? raw : DEFAULT_SORT_DIRECTION
}

export function useSortParams() {
  const [params, setParams] = useSearchParams()
  const sortField = parseSortField(params)
  const sortDirection = parseSortDirection(params)

  const onSortFieldChange = useCallback(
    (field: RuleSortField) => {
      setParams(
        prevParams => {
          const next = new URLSearchParams(prevParams)
          next.set('sort_field', field)
          serializeCursor(null, next)
          return next
        },
        {
          preventScrollReset: true,
        },
      )
    },
    [setParams],
  )

  const onSortDirectionChange = useCallback(
    (direction: RuleSortDirection) => {
      setParams(
        prevParams => {
          const next = new URLSearchParams(prevParams)
          next.set('sort_direction', direction)
          serializeCursor(null, next)
          return next
        },
        {
          preventScrollReset: true,
        },
      )
    },
    [setParams],
  )

  return {
    sortField,
    sortDirection,
    onSortFieldChange,
    onSortDirectionChange,
  }
}
