import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {repoCodeQualityShowRoute} from './repo-code-quality-show-route'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'
import {Heading, RelativeTime, Link} from '@primer/react'
import {codeQualityIndexPath} from '@github-ui/paths'
import {RuleCategoryBadge} from '../components/RuleCategoryBadge'
import {ExpandableContent} from '../components/ExpandableContent'
import {MarkdownRenderer} from '@github-ui/copilot-markdown'
import {RuleSeverityBadge} from '@github-ui/code-scanning-shared/components/RuleSeverityBadge'
import {RuleFindings} from '../components/RuleFindings'

import styles from './RepoCodeQualityShow.module.css'
import {RuleLanguageLabel} from '../components/RuleLanguageLabel'
import {mapLanguageStringToRuleLanguage} from '../types/rule-language'
import {ArrowLeftIcon} from '@primer/octicons-react'

export function RepoCodeQualityShow() {
  const payload = useRouteQuery(repoCodeQualityShowRoute, 'mainQuery')
  const {
    owner,
    repo,
    defaultBranch,
    branchListCacheKey,
    ruleId,
    ruleTitle,
    ruleDescription,
    ruleHelp,
    ruleCategory,
    ruleSeverity,
    ruleLanguage,
    lastScanAt,
    canAutofix,
    canDismiss,
    hasRepoWriteAccess,
  } = payload.data

  const ruleHelpMarkdown = <MarkdownRenderer markdown={ruleHelp} />
  const parsedLanguage = mapLanguageStringToRuleLanguage(ruleLanguage)

  return (
    <>
      <Link href={codeQualityIndexPath({owner, repo})}>
        <ArrowLeftIcon /> Standard findings
      </Link>

      <div className="d-flex flex-items-center flex-justify-between gap-2 tmp-mt-3">
        <Heading as="h1" className="h3">
          {ruleTitle}
        </Heading>
        <BetaLabel />
      </div>
      <span className="color-fg-muted f8 tmp-mb-4" data-testid="last-scan-date">
        Last scan: <RelativeTime date={new Date(lastScanAt)} prefix="" />
      </span>
      <div className={styles.mainContent}>
        <div className={styles.content}>
          <ExpandableContent collapsedContent={ruleDescription} expandedContent={ruleHelpMarkdown} />
          <RuleFindings
            owner={owner}
            repo={repo}
            defaultBranch={defaultBranch}
            branchListCacheKey={branchListCacheKey}
            ruleId={ruleId}
            ruleTitle={ruleTitle}
            canAutofix={canAutofix}
            canDismiss={canDismiss}
            hasRepoWriteAccess={hasRepoWriteAccess}
          />
        </div>
        <div className={styles.sidebar}>
          <div>
            <p className="mb-1 color-fg-muted f6">
              <strong>Category</strong>
            </p>
            <RuleCategoryBadge category={ruleCategory} />
          </div>
          <hr className={styles.line} />
          <div>
            <p className="mb-1 color-fg-muted f6">
              <strong>Severity</strong>
            </p>
            <RuleSeverityBadge severity={ruleSeverity} />
          </div>
          <hr className={styles.line} />
          {parsedLanguage && (
            <>
              <div>
                <p className="mb-1 color-fg-muted f6">
                  <strong>Language</strong>
                </p>
                <RuleLanguageLabel language={parsedLanguage} />
              </div>
              <hr className={styles.line} />
            </>
          )}
        </div>
      </div>
    </>
  )
}
