import {useCallback, useMemo, useState} from 'react'
import {
  CreateBranchDialog,
  type OnCreateBranchData,
  type OnCreateBranchOptions,
} from '@github-ui/code-scanning-shared/components/CreateBranchDialog'
import {useCommitAutofixMutation} from '../hooks/use-commit-autofix-mutation'
import {codeQualityFindingsAutofixCommitPath} from '@github-ui/paths'
import type {Repository} from '@github-ui/code-scanning-shared/types/repository'
import {CodeQualityCommitFixButton} from './CodeQualityCommitFixButton'
import {isFeatureEnabled} from '@github-ui/feature-flags'

export interface CommitAutofixButtonProps {
  findingStableId: string
  ruleTitle: string
  owner: string
  repo: string
  defaultBranch: string
  branchListCacheKey: string
}

export function CommitAutofixButton({
  findingStableId,
  ruleTitle,
  owner,
  repo,
  defaultBranch,
  branchListCacheKey,
}: CommitAutofixButtonProps) {
  const [showCreateBranchDialog, setShowCreateBranchDialog] = useState(false)
  const showPageImprovementsFFEnabled = isFeatureEnabled('code_quality_backlog_rule_show')

  const handleClose = useCallback(() => {
    setShowCreateBranchDialog(false)
  }, [])

  const {
    isPending,
    error,
    mutate,
    data: mutationResponse,
  } = useCommitAutofixMutation(
    codeQualityFindingsAutofixCommitPath({
      owner,
      repo,
      findingStableId,
    }),
  )

  const onCreateBranch = useCallback(
    (data: OnCreateBranchData, {onSuccess}: OnCreateBranchOptions) => {
      mutate(
        {
          name: data.branchName,
          createNewBranch: data.createNewBranch,
          createDraftPR: data.createPullRequest,
          commitMessage: data.commitMessage ?? '',
          extendedDescription: data.extendedDescription,
        },
        {
          onSuccess: response => {
            onSuccess({
              branchName: response.branchName,
              pullRequest: response.pullRequest,
              errorMessages: response.messages,
            })
          },
        },
      )
    },
    [mutate],
  )

  const repository = useMemo(
    (): Repository => ({
      ownerLogin: owner,
      name: repo,
      defaultBranch,
    }),
    [owner, repo, defaultBranch],
  )

  return (
    <>
      <CodeQualityCommitFixButton
        isPrBeingCreated={isPending}
        setShowCreateBranchDialog={setShowCreateBranchDialog}
        buttonSize="small"
        isInvisibleVariant={showPageImprovementsFFEnabled}
      />

      {showCreateBranchDialog && (
        <CreateBranchDialog
          repository={repository}
          branchListCacheKey={branchListCacheKey}
          branchType="new" // Allow user to type in a branch name and let the controller create or reuse the branch
          dialogTitle="Commit autofix to branch"
          submitButtonContent="Commit change"
          showCommitMessageField={false}
          showPullRequestNextStep
          initialNextStep="pr"
          initialBranchName={`finding-autofix-${findingStableId.substring(0, 8)}`}
          initialCommitMessage={`Fix for ${ruleTitle}`}
          onCancel={handleClose}
          onClose={handleClose}
          onCreateBranch={onCreateBranch}
          isPending={isPending}
          error={error}
          createdPullRequest={mutationResponse?.pullRequest}
        />
      )}
    </>
  )
}
