import {type ChangeEvent, useCallback, useMemo} from 'react'
import {ActionList, Banner, Checkbox, Tooltip, IconButton} from '@primer/react'
import {ShieldSlashIcon} from '@primer/octicons-react'
import {ActionBar, type ActionBarProps} from '@github-ui/action-bar'
import {useQueryClient} from '@github-ui/react-query'
import {useRuleFindingsBulkStateMutation} from '../hooks/use-rule-findings-bulk-state-mutation'
import {FindingState} from '../types/rule-finding'
import type {RuleFinding} from '../types/rule-finding'
import styles from './RuleFindingsBulkActions.module.css'
import pluralize from 'pluralize'

interface RuleFindingsBulkActionsProps {
  selectedItems: Set<string>
  findings: RuleFinding[]
  totalCount: number
  ruleId: string
  ruleFindingsPath: string
  onSuccess: () => void
  onToggleSelectAll: (selectAll: boolean) => void
}

export function RuleFindingsBulkActions({
  selectedItems,
  findings,
  totalCount,
  ruleId,
  ruleFindingsPath,
  onSuccess,
  onToggleSelectAll,
}: RuleFindingsBulkActionsProps) {
  const queryClient = useQueryClient()
  const {mutate: mutateBulkState, isPending, isError} = useRuleFindingsBulkStateMutation(ruleFindingsPath)

  const selectedCount = selectedItems.size
  const findingsPageCount = findings.length
  const allSelected = findingsPageCount > 0 && selectedCount === findingsPageCount
  const someSelected = selectedCount > 0 && selectedCount < findingsPageCount

  const hasOpenSelected = useMemo(() => {
    return findings.some(f => selectedItems.has(f.stableId) && f.findingState === FindingState.Open)
  }, [findings, selectedItems])

  const handleDismiss = useCallback(() => {
    const openFindings = findings.filter(f => selectedItems.has(f.stableId) && f.findingState === FindingState.Open)

    if (openFindings.length === 0) return

    mutateBulkState(
      {
        ruleId,
        findings: openFindings.map(f => ({stableId: f.stableId, filePath: f.filePath})),
        state: FindingState.Dismissed,
      },
      {
        onSuccess: () => {
          queryClient.invalidateQueries({queryKey: ['rule-findings']})
          onSuccess()
        },
      },
    )
  }, [findings, selectedItems, ruleId, mutateBulkState, queryClient, onSuccess])

  const handleSelectAllChange = (e: ChangeEvent<HTMLInputElement>) => {
    onToggleSelectAll(e.target.checked)
  }

  const actions = useMemo<ActionBarProps['actions']>(() => {
    if (selectedCount === 0) return []

    return [
      {
        key: 'dismissFindings',
        render: (isOverflowMenu: boolean) => {
          if (isOverflowMenu) {
            return (
              <ActionList.Item disabled={!hasOpenSelected || isPending} onSelect={handleDismiss}>
                Dismiss
              </ActionList.Item>
            )
          }
          return (
            <Tooltip text={hasOpenSelected ? 'Dismiss selected findings' : 'No open findings selected'}>
              <IconButton
                icon={ShieldSlashIcon}
                aria-label="Dismiss selected findings"
                disabled={!hasOpenSelected || isPending}
                onClick={handleDismiss}
                size="small"
                loading={isPending}
              />
            </Tooltip>
          )
        },
      },
    ]
  }, [selectedCount, hasOpenSelected, isPending, handleDismiss])

  return (
    <>
      {isError && (
        <Banner
          hideTitle
          variant="critical"
          title="Error dismissing findings"
          description="Could not dismiss the selected findings. Please try again."
          className="mb-2"
        />
      )}
      <div className={styles.bulkActionsBar}>
        <Checkbox
          checked={allSelected}
          indeterminate={someSelected}
          onChange={handleSelectAllChange}
          aria-label={allSelected ? 'Deselect all findings' : 'Select all findings'}
        />
        <span className={styles.countText}>
          {selectedCount > 0
            ? `${selectedCount} of ${totalCount} selected`
            : `${totalCount} ${pluralize('finding', totalCount)}`}
        </span>
        {selectedCount > 0 && <ActionBar actions={actions} label="findings bulk actions" density="condensed" />}
      </div>
    </>
  )
}
