import {Banner, Button, Dialog, Link} from '@primer/react'
import {useState} from 'react'
import {RecentActivityCommitFixDialog} from './RecentActivityCommitFixDialog'
import type {SuggestedFixFile} from '../types/suggested-fix'

export type RecentActivityFindingsCopilotNotEnabledDialogProps = {
  copilotCodingAgentDocsUrl: string
  showFixWithoutCopilotButton: boolean
  suggestedFixFiles: SuggestedFixFile[]
  owner: string
  repo: string
  branch: string
  branchListCacheKey: string
  onClose: () => void
}

export function RecentActivityFindingsCopilotNotEnabledDialog({
  copilotCodingAgentDocsUrl,
  showFixWithoutCopilotButton,
  suggestedFixFiles,
  owner,
  repo,
  branch,
  branchListCacheKey,
  onClose,
}: RecentActivityFindingsCopilotNotEnabledDialogProps) {
  const [showCreateBranchDialog, setShowCreateBranchDialog] = useState(false)

  if (showCreateBranchDialog) {
    return (
      <RecentActivityCommitFixDialog
        suggestedFixFiles={suggestedFixFiles}
        owner={owner}
        repo={repo}
        defaultBranch={branch}
        branchListCacheKey={branchListCacheKey}
        onClose={() => setShowCreateBranchDialog(false)}
      />
    )
  }

  return (
    <Dialog
      title="Fix findings with Copilot"
      onClose={onClose}
      renderFooter={() => (
        <Dialog.Footer>
          <Button onClick={onClose}>Cancel</Button>
          {showFixWithoutCopilotButton && (
            <Button variant="primary" onClick={() => setShowCreateBranchDialog(true)}>
              Open pull request
            </Button>
          )}
        </Dialog.Footer>
      )}
    >
      <Banner
        hideTitle
        aria-label="Assign findings to Copilot"
        description={
          <div data-a11y-link-underlines="true">
            To assign findings to Copilot, you need access to{' '}
            <Link inline href={copilotCodingAgentDocsUrl} target="_blank" rel="noopener noreferrer">
              GitHub Copilot Coding Agent
            </Link>
            .
          </div>
        }
        title="Info"
        variant="upsell"
      />
      <p className="tmp-mt-3">
        Copilot Coding Agent can open a pull request and grab context around your codebase to implement autofixes and
        resolve any conflicts that may come up.
      </p>
      <p className="mb-0">
        You can also choose to open a pull request and assign it to Copilot later, or commit the changes manually.
      </p>
    </Dialog>
  )
}
